effect.shader:
void main() {
    vec4 cor = texture(inputImg, acScreenNorm);
    // medido: os pesos da luminância de lá
    float y = dot(cor.rgb, vec3(0.299, 0.587, 0.114));
    vec3 alvo = mix(mapBlackTo.rgb, mapWhiteTo.rgb, y);
    fragColor = vec4(mix(cor.rgb, alvo, clamp(amountToTint / 100.0, 0.0, 1.0)), cor.a);
}
